By $L$-smoothness, Taylor expansion gives:
\begin{align}
\Delta l_i = \epsilon \langle \nabla L(\theta_t; B_t), u_i \rangle + \frac{\epsilon^2}{2} u_i^\top H(\theta_t; B_t) u_i + R_i + n_i,
\end{align}
where $H = \nabla^2 L(\theta_t; B_t)$ with $\|H\| \leq L$, $|R_i| \leq \mathcal{O}(\epsilon^3 d^{3/2} L)$, $\text Var[R_i] \leq \mathcal{O}(\epsilon^6 d^3 L^2)$, and $\text Var[n_i] \leq 2V^2$.

Then, $\mathbb{E}[\Delta l_i] = \mathcal{O}(\epsilon^2 d L)$ and
\begin{align}
\text Var[\Delta l_i] = \epsilon^2 \|\nabla L(\theta_t; B_t)\|^2 + \mathcal{O}(\epsilon^4 d L^2) + 2V^2 \leq \epsilon^2 G^2 + 2V^2 + \mathcal{O}(\epsilon^4 d L^2).
\end{align}

Let $v = \text Var[\Delta l_i]$. Thus, $\mathbb{E}[\sigma_t] \approx \sqrt{v} \approx \epsilon \|\nabla L(\theta_t; B_t)\|$ (with bias $\mathcal{O}(\epsilon^2 \sqrt{d} L)$ assuming $V \ll \epsilon G$ and small $\epsilon$).

$\sigma_t^2$ is the (biased) empirical variance, equivalent to a U-statistic of order 2 with kernel $h(x,y) = (x-y)^2/2$, where $\mathbb{E}[h(X,Y)] = v$.

By Hoeffding decomposition (boucheron2013concentration),
\begin{align}
\text Var[\sigma_t^2] = \mathcal{O}\left( \frac{\zeta_1}{m} + \frac{\zeta_2}{m^2} \right),
\end{align}
with $\zeta_1 = \text Var(\mathbb{E}[h(X,Y) \mid X]) = \frac{1}{4} (\mathbb{E}[(X - \mu)^4] - v^2) \leq \mathcal{O}(v^2)$ (by sub-Gaussianity, (vershynin2018high), $\mathbb{E}[|X - \mu|^4] \leq C v^2$ for constant $C$), and $\zeta_2 = \text Var(h(X,Y)) \leq M^4$ where $M = \mathcal{O}(\epsilon G \sqrt{d} + \epsilon^2 d L + V \sqrt{\log m})$.

Thus,
\begin{align}
\text Var[\sigma_t^2] = \mathcal{O}\left( \frac{v^2}{m} + \frac{M^4}{m^2} \right).
\end{align}

By delta method,
\begin{align}
\text Var[\sigma_t] \leq \mathcal{O}\left( \frac{v}{m} + \frac{M^4}{m^2 v} \right) = \mathcal{O}\left( \frac{\epsilon^2 G^2 + V^2}{m} + \frac{\epsilon^2 d^2 G^2}{m^2} \right),
\end{align}
simplified to the stated bound (log factors absorbed).

For high-probability, Bernstein's inequality (vershynin2018high) on $\sigma_t^2$ yields
\begin{align}
|\sigma_t^2 - v| \leq \mathcal{O}\left( v \sqrt{\frac{\log \delta^{-1}}{m}} + M \frac{\log \delta^{-1}}{m} \right),
\end{align}
implying
\begin{align}
|\sigma_t - \sqrt{v}| &\leq \mathcal{O}\left( \sqrt{\frac{v \log \delta^{-1}}{m}} + \frac{M \log \delta^{-1}}{m \sqrt{v}} \right) \\
&= \mathcal{O}\left( \epsilon G \sqrt{\frac{\log \delta^{-1}}{m}} + V \sqrt{\frac{\log \delta^{-1}}{m}} + \frac{\epsilon \sqrt{d} \log \delta^{-1}}{m} \right).
\end{align}
